/**
 * Load the built 9Router plugin for OpenCode's local-directory resolver.
 *
 * OpenCode V2 resolves an absolute plugin directory through its `server`
 * entrypoint. Published packages use the equivalent `./server` export from
 * package.json; this bridge keeps local development and V1-style paths aligned.
 */
export { default } from "./dist/index.js";
export * from "./dist/index.js";

import { Plugin } from "@opencode/plugin";
import { NineRouterPlugin } from "./plugin.js";
import { nineRouterV2 } from "./v2.js";
// ── Dual V1 + V2 Package Entry ──────────────────────────────
/**
 * Combined plugin export. OpenCode V2 reads the `setup`/`id` fields produced by
 * `Plugin.define`; OpenCode V1 (1.18.29+) reads the `server` field. Both
 * implementations share the same discovery core.
 *
 * `nineRouterV2` is passed through `Plugin.define` for validation, but the
 * default export is written as an explicit object literal so the emitted
 * declaration is stable and clearly includes `id`, `setup`, and `server`.
 */
const v2 = Plugin.define(nineRouterV2);
export default {
    id: v2.id,
    setup: v2.setup,
    server: NineRouterPlugin,
};
// Named export retained for V1 consumers that import it directly.
export { NineRouterPlugin };

import { DEFAULT_BASE_URL, DISCOVERY_CACHE_TTL, DISCOVERY_TIMEOUT, PLUGIN_NAME, PROVIDER_DISPLAY_NAME, } from "./constants.js";
import { discoverModels } from "./discovery.js";
import { ensureAPIPath, normalizeBaseURL } from "./utils.js";
// ── Plugin Entry ────────────────────────────────────────────
/**
 * OpenCode plugin provider for 9Router. Registers a "9router" provider and,
 * in the config hook, auto-discovers models (enriched with capabilities and
 * token limits) for every configured 9router-family provider.
 */
export const NineRouterPlugin = async ({ client }) => {
    const log = async (level, message) => {
        try {
            await client.app.log({
                body: {
                    service: "9router-provider",
                    level,
                    message,
                },
            });
        }
        catch {
            // Logging is best-effort
        }
    };
    return {
        config: async (config) => {
            config.provider ??= {};
            const provider = config.provider;
            // Collect all existing providers whose key starts with "9router"
            const providerKeys = Object.keys(provider).filter((k) => k.startsWith("9router"));
            // Backward compat: if no 9router-family providers exist, register the default one
            if (providerKeys.length === 0) {
                config.provider[PLUGIN_NAME] = {
                    npm: "@ai-sdk/openai-compatible",
                    name: PROVIDER_DISPLAY_NAME,
                    options: {
                        baseURL: DEFAULT_BASE_URL,
                    },
                    models: {},
                };
                providerKeys.push(PLUGIN_NAME);
            }
            // Process each 9router-family provider independently
            const results = await Promise.allSettled(providerKeys.map(async (key) => {
                const existing = provider[key];
                const options = existing?.options;
                const baseURL = options?.baseURL ?? DEFAULT_BASE_URL;
                const apiKey = options?.apiKey;
                const normalizedURL = normalizeBaseURL(baseURL);
                const apiURL = ensureAPIPath(normalizedURL);
                // Per-provider cache configuration
                const cacheEnabled = options?.cache ?? true;
                const cacheTTL = options?.cacheTTL ?? DISCOVERY_CACHE_TTL;
                const discoveryTimeout = options?.discoveryTimeout ?? DISCOVERY_TIMEOUT;
                const discovered = await discoverModels(normalizedURL, apiKey, cacheEnabled, cacheTTL, discoveryTimeout, key, log);
                const entry = provider[key];
                entry.npm ??= "@ai-sdk/openai-compatible";
                entry.name ??= key;
                entry.api = apiURL;
                entry.options = { ...entry.options, baseURL: apiURL };
                // Catalog controls are V2 overlays, not legacy model configuration keys.
                entry.models = Object.fromEntries(Object.entries(discovered ?? {}).map(([id, model]) => {
                    const { reasoning_options, ...legacy } = model;
                    return [id, legacy];
                }));
                return { key, discovered, apiURL };
            }));
            // Log results
            for (const result of results) {
                if (result.status === "fulfilled") {
                    const { key, discovered, apiURL } = result.value;
                    if (discovered) {
                        await log("info", `[${key}] Discovered ${Object.keys(discovered).length} models from ${apiURL}`);
                    }
                    else {
                        await log("warn", `[${key}] Failed to discover models from ${apiURL}. Check if the service is running and accessible.`);
                    }
                }
                else {
                    await log("error", `Provider pipeline error: ${result.reason}`);
                }
            }
        },
    };
};
